/**
 * @ingroup iface_zcr_color_manager_v1
 * @struct zcr_color_manager_v1_interface
 */
struct zcr_color_manager_v1_interface {
	/**
	 * create a color space object from ICC profiles
	 *
	 * Create a color space object from an ICC profile. This request
	 * returns a zcr_color_space_creator_v1 object which either returns
	 * an error or the successfully created zcr_color_space_v1 object.
	 *
	 * The description of the color space to create is sent in the form
	 * of an ICC profile as a file descriptor in the argument icc.
	 *
	 * The fd must be seekable and the maximum size of the ICC profile
	 * is 4 MB. Violating these requirements will raise an icc_fd
	 * protocol error. A compositor must not modify the contents of the
	 * file, and the fd may be sealed for writes and size changes.
	 *
	 * The file contents must represent a valid ICC profile. The ICC
	 * profile version must be 2 or 4, it must be a 3 channel profile
	 * and the class must be 'input', 'output', 'abstract' or
	 * 'display'. Violating these requirements will not result in a
	 * protocol error but raise the zcr_color_space_creator_v1.error
	 * event.
	 *
	 * See the zcr_color_space_v1 and zcr_color_space_creator_v1
	 * interface for more details about the created object.
	 *
	 * See the specification from International Color Consortium for
	 * more details about ICC profiles, also known as ISO 15076-1:2010.
	 */
	void (*create_color_space_from_icc)(struct wl_client *client,
					    struct wl_resource *resource,
					    uint32_t id,
					    int32_t icc);
	/**
	 * create a color space object from well-known names
	 *
	 * [Deprecated] Create a color space object from well-known
	 * names. This request returns a zcr_color_space_creator_v1 object
	 * which either returns an error or the successfully created
	 * zcr_color_space_v1 object.
	 *
	 * EOTF, chromaticity and whitepoint must not be unknown.
	 * Otherwise, or if a given value is not listed in the enumeration,
	 * the protocol error bad_enum is raised.
	 *
	 * See the zcr_color_space_v1 and zcr_color_space_creator_v1
	 * interface for more details about the created object. Use
	 * create_color_space_from_complete_names instead.
	 * @param eotf EOTF
	 * @param chromaticity chromaticity
	 * @param whitepoint whitepoint
	 */
	void (*create_color_space_from_names)(struct wl_client *client,
					      struct wl_resource *resource,
					      uint32_t id,
					      uint32_t eotf,
					      uint32_t chromaticity,
					      uint32_t whitepoint);
	/**
	 * create a color space object from parameters
	 *
	 * [Deprecated] Create a color space object from parameters. This
	 * request returns a zcr_color_space_creator_v1 object which either
	 * returns an error or the successfully created zcr_color_space_v1
	 * object.
	 *
	 * EOTF must not be unknown. Otherwise, or if a given EOTF is not
	 * listed in the enumeration, the protocol error bad_enum is
	 * raised.
	 *
	 * The white point must be inside the triangle created by the red,
	 * green and blue primaries. Otherwise the bad_param protocol error
	 * is raised.
	 *
	 * All the chromaticity values are multiplied by 10000 to produce
	 * the integers carried by the protocol.
	 *
	 * See the zcr_color_space_v1 and zcr_color_space_creator_v1
	 * interface for more details about the created object. Use
	 * create_color_space_from_complete_params instead.
	 * @param eotf EOTF
	 * @param primary_r_x red primary X * 10000
	 * @param primary_r_y red primary Y * 10000
	 * @param primary_g_x green primary X * 10000
	 * @param primary_g_y green primary Y * 10000
	 * @param primary_b_x blue primary X * 10000
	 * @param primary_b_y blue primary Y * 10000
	 * @param white_point_x white point X * 10000
	 * @param white_point_y white point Y * 10000
	 */
	void (*create_color_space_from_params)(struct wl_client *client,
					       struct wl_resource *resource,
					       uint32_t id,
					       uint32_t eotf,
					       uint32_t primary_r_x,
					       uint32_t primary_r_y,
					       uint32_t primary_g_x,
					       uint32_t primary_g_y,
					       uint32_t primary_b_x,
					       uint32_t primary_b_y,
					       uint32_t white_point_x,
					       uint32_t white_point_y);
	/**
	 * create a color management interface for a wl_output
	 *
	 * This creates a new zcr_color_management_output_v1 object for
	 * the given wl_output.
	 *
	 * See the zcr_color_management_output_v1 interface for more
	 * details.
	 */
	void (*get_color_management_output)(struct wl_client *client,
					    struct wl_resource *resource,
					    uint32_t id,
					    struct wl_resource *output);
	/**
	 * create a color management interface for a wl_surface
	 *
	 * This creates a new color zcr_color_management_surface_v1
	 * object for the given wl_surface.
	 *
	 * See the zcr_color_management_surface_v1 interface for more
	 * details.
	 */
	void (*get_color_management_surface)(struct wl_client *client,
					     struct wl_resource *resource,
					     uint32_t id,
					     struct wl_resource *surface);
	/**
	 * destroy the color manager
	 *
	 * Destroy the zcr_color_manager_v1 object. This does not affect
	 * any other objects in any way.
	 */
	void (*destroy)(struct wl_client *client,
			struct wl_resource *resource);
	/**
	 * create a color space object from well-known names
	 *
	 * Create a color space object from well-known names. This
	 * request returns a zcr_color_space_creator_v1 object which either
	 * returns an error or the successfully created zcr_color_space_v1
	 * object.
	 *
	 * EOTF, chromaticity and whitepoint must not be unknown.
	 * Otherwise, or if a given value is not listed in the enumeration,
	 * the protocol error bad_enum is raised.
	 *
	 * This request additionally includes matrix and range information.
	 *
	 * See the zcr_color_space_v1 and zcr_color_space_creator_v1
	 * interface for more details about the created object.
	 * @param eotf EOTF
	 * @param chromaticity chromaticity
	 * @param whitepoint whitepoint
	 * @param matrix color matrix
	 * @param range color range
	 * @since 3
	 */
	void (*create_color_space_from_complete_names)(struct wl_client *client,
						       struct wl_resource *resource,
						       uint32_t id,
						       uint32_t eotf,
						       uint32_t chromaticity,
						       uint32_t whitepoint,
						       uint32_t matrix,
						       uint32_t range);
	/**
	 * create a color space object from parameters
	 *
	 * Create a color space object from parameters. This request
	 * returns a zcr_color_space_creator_v1 object which either returns
	 * an error or the successfully created zcr_color_space_v1 object.
	 *
	 * EOTF must not be unknown. Otherwise, or if a given EOTF is not
	 * listed in the enumeration, the protocol error bad_enum is
	 * raised.
	 *
	 * The white point must be inside the triangle created by the red,
	 * green and blue primaries. Otherwise the bad_param protocol error
	 * is raised.
	 *
	 * All the chromaticity values are multiplied by 10000 to produce
	 * the integers carried by the protocol.
	 *
	 * This request additionally includes matrix and range information.
	 *
	 * See the zcr_color_space_v1 and zcr_color_space_creator_v1
	 * interface for more details about the created object.
	 * @param eotf EOTF
	 * @param matrix Color matrix
	 * @param range Color range
	 * @param primary_r_x red primary X * 10000
	 * @param primary_r_y red primary Y * 10000
	 * @param primary_g_x green primary X * 10000
	 * @param primary_g_y green primary Y * 10000
	 * @param primary_b_x blue primary X * 10000
	 * @param primary_b_y blue primary Y * 10000
	 * @param white_point_x white point X * 10000
	 * @param white_point_y white point Y * 10000
	 * @since 3
	 */
	void (*create_color_space_from_complete_params)(struct wl_client *client,
							struct wl_resource *resource,
							uint32_t id,
							uint32_t eotf,
							uint32_t matrix,
							uint32_t range,
							uint32_t primary_r_x,
							uint32_t primary_r_y,
							uint32_t primary_g_x,
							uint32_t primary_g_y,
							uint32_t primary_b_x,
							uint32_t primary_b_y,
							uint32_t white_point_x,
							uint32_t white_point_y);
};


