/**
 * @ingroup iface_zcr_color_management_output_v1
 * @struct zcr_color_management_output_v1_interface
 */
struct zcr_color_management_output_v1_interface {
	/**
	 * get the color space of the output
	 *
	 * This creates a new zcr_color_space_v1 object for the current
	 * color space of the output. There always is exactly one color
	 * space active for an output so the client should destroy the
	 * color space created by earlier invocations of this request. This
	 * request is usually sent as a reaction to the color_space_changed
	 * event or when creating a zcr_color_management_output_v1 object.
	 *
	 * The created zcr_color_space_v1 object preserves the color space
	 * of the output from the time the object was created.
	 *
	 * The resulting color space object allows get_information request.
	 *
	 * See the zcr_color_space_v1 interface for more details.
	 */
	void (*get_color_space)(struct wl_client *client,
				struct wl_resource *resource,
				uint32_t id);
	/**
	 * destroy the color management output
	 *
	 * Destroy the color zcr_color_management_output_v1 object. This
	 * does not affect any remaining protocol objects.
	 */
	void (*destroy)(struct wl_client *client,
			struct wl_resource *resource);
};

