#ifndef ZCR_COLOR_MANAGEMENT_SURFACE_V1_RENDER_INTENT_ENUM
#define ZCR_COLOR_MANAGEMENT_SURFACE_V1_RENDER_INTENT_ENUM
/**
 * @ingroup iface_zcr_color_management_surface_v1
 * render intent
 *
 *
 * Rendering intent allow the client to hint at how to perform color space
 * transformations.
 *
 * See the ICC specification for more details about rendering intent.
 */
enum zcr_color_management_surface_v1_render_intent {
	/**
	 * perceptual
	 */
	ZCR_COLOR_MANAGEMENT_SURFACE_V1_RENDER_INTENT_PERCEPTUAL = 0,
	/**
	 * media-relative colorimetric
	 */
	ZCR_COLOR_MANAGEMENT_SURFACE_V1_RENDER_INTENT_RELATIVE = 1,
	/**
	 * saturation
	 */
	ZCR_COLOR_MANAGEMENT_SURFACE_V1_RENDER_INTENT_SATURATION = 2,
	/**
	 * ICC-absolute colorimetric
	 */
	ZCR_COLOR_MANAGEMENT_SURFACE_V1_RENDER_INTENT_ABSOLUTE = 3,
	/**
	 * media-relative colorimetric + black point compensation
	 */
	ZCR_COLOR_MANAGEMENT_SURFACE_V1_RENDER_INTENT_RELATIVE_BPC = 4,
};
#endif /* ZCR_COLOR_MANAGEMENT_SURFACE_V1_RENDER_INTENT_ENUM */

#ifndef ZCR_COLOR_MANAGEMENT_SURFACE_V1_ALPHA_MODE_ENUM
#define ZCR_COLOR_MANAGEMENT_SURFACE_V1_ALPHA_MODE_ENUM
/**
 * @ingroup iface_zcr_color_management_surface_v1
 * alpha mode
 *
 * Specifies whether alpha is pre-multiplied into color channels or not.
 * If pre-multiplied, the linear alpha value is already multiplied with the
 * (non-linear) color channel code values in the color channels.
 */
enum zcr_color_management_surface_v1_alpha_mode {
	/**
	 * alpha is independent from color channels
	 */
	ZCR_COLOR_MANAGEMENT_SURFACE_V1_ALPHA_MODE_STRAIGHT = 0,
	/**
	 * alpha is pre-multiplied into color channels
	 */
	ZCR_COLOR_MANAGEMENT_SURFACE_V1_ALPHA_MODE_PREMULTIPLIED = 1,
};
#endif /* ZCR_COLOR_MANAGEMENT_SURFACE_V1_ALPHA_MODE_ENUM */

/**
 * @ingroup iface_zcr_color_management_surface_v1
 * @struct zcr_color_management_surface_v1_interface
 */
struct zcr_color_management_surface_v1_interface {
	/**
	 * set the surface alpha mode
	 *
	 * Assuming an alpha channel exists, it is always linear. The
	 * alpha mode determines whether the color channels include alpha
	 * pre-multiplied or not. Using straight alpha might have
	 * performance benefits.
	 *
	 * Alpha mode is double buffered, and will be applied at the time
	 * wl_surface.commit of the corresponding wl_surface is called.
	 *
	 * By default, a surface is assumed to have pre-multiplied alpha.
	 * @param alpha_mode alpha mode
	 */
	void (*set_alpha_mode)(struct wl_client *client,
			       struct wl_resource *resource,
			       uint32_t alpha_mode);
	/**
	 * set the content extended dynamic range
	 *
	 * Set the extended dynamic range (EDR) value for the underlying
	 * surface. The EDR value is double buffered, and will be applied
	 * at the time wl_surface.commit of the corresponding wl_surface is
	 * called.
	 *
	 * The EDR value describes how much dynamic range is encoded
	 * relative to the SDR maximum white. EDR value is proportional to
	 * luminance, using the luminance of black as the zero level. A
	 * value of 1.0 means that the SDR maximum white is the highest
	 * possible luminance of the surface. A value of 3.0 means that the
	 * SDR maximum white is one third of the highest possible luminance
	 * of the surface.
	 *
	 * The color space attached to the surface can make the code values
	 * in the buffer non-linear in regards to the luminance. The code
	 * value to produce a third of the luminance of the biggest code
	 * value therefore might not be one third of the biggest code
	 * value.
	 *
	 * For the definition of the SDR maximum white on an output, see
	 * zcr_color_management_output_v1.extended_dynamic_range. Content
	 * producers are free to choose their SDR maximum white level. How
	 * it shall be displayed depends on the monitor capabilities and
	 * the output EDR value.
	 *
	 * By default the EDR value is 1.0. The compositor will tone map
	 * the image to match the EDR of each output the surface is shown
	 * on. The aim for the EDR-EDR mapping is to produce a relative
	 * luminance mapping that looks equally good regardless of the
	 * viewing conditions and the monitor capabilities, assuming the
	 * output EDR value was tuned to the output capabilities and the
	 * viewing environment. There might be performance and image
	 * quality benefits from providing content readily tone mapped to
	 * the EDR value of the output the surface is shown on.
	 *
	 * The EDR value is multiplied by 1000 to produce the integer value
	 * carried by the protocol.
	 * @param value EDR value * 1000
	 */
	void (*set_extended_dynamic_range)(struct wl_client *client,
					   struct wl_resource *resource,
					   uint32_t value);
	/**
	 * set the surface color space
	 *
	 * Set the color space of the underlying surface. The color space
	 * and render intent are double buffered, and will be applied at
	 * the time wl_surface.commit of the corresponding wl_surface is
	 * called.
	 *
	 * The render intent gives the compositor a hint what to optimize
	 * for in color space transformations.
	 *
	 * By default, a surface is assumed to have the sRGB color space
	 * and an arbitrary render intent.
	 *
	 * If the color space of the surface matches the color space of an
	 * output it is shown on the performance and color accuracy might
	 * improve. To find those color spaces the client can listen to the
	 * preferred_color_space or the wl_surface.enter/leave events. This
	 * improvement may require using the color space object created by
	 * zcr_color_management_output_v1.get_color_space.
	 * @param render_intent render intent
	 */
	void (*set_color_space)(struct wl_client *client,
				struct wl_resource *resource,
				struct wl_resource *color_space,
				uint32_t render_intent);
	/**
	 * set the surface color space to default
	 *
	 * This request sets the surface color space to the defaults, see
	 * set_color_space. The setting will be applied at the time
	 * wl_surface.commit of the corresponding wl_surface is called.
	 */
	void (*set_default_color_space)(struct wl_client *client,
					struct wl_resource *resource);
	/**
	 * destroy the color management interface for a surface
	 *
	 * Destroy the zcr_color_management_surface_v1 object.
	 *
	 * When the last zcr_color_management_surface_v1 object for a
	 * wl_surface is destroyed, the destruction will pend unsetting the
	 * wl_surface's color space, render intent and alpha mode similar
	 * to set_color_space will pend a set.
	 */
	void (*destroy)(struct wl_client *client,
			struct wl_resource *resource);
};

