/**
 * @ingroup iface_zcr_color_space_v1
 * @struct zcr_color_space_v1_interface
 */
struct zcr_color_space_v1_interface {
	/**
	 * get information about the color space
	 *
	 * As a reply to this request, the compositor will send all
	 * available information events describing this color space object
	 * and finally the 'done' event. Other extensions may define more
	 * events to be sent before 'done'.
	 *
	 * This request is allowed only on zcr_color_space_v1 objects where
	 * the message that created the object specifies that
	 * get_information is allowed. Otherwise protocol error
	 * no_information is raised.
	 *
	 * Every get_information request on the same object will always
	 * return the exact same data.
	 *
	 * See zcr_color_management_output_v1.get_color_space and
	 * zcr_color_space_creator_v1.created.
	 */
	void (*get_information)(struct wl_client *client,
				struct wl_resource *resource);
	/**
	 * destroy the color space
	 *
	 * Destroy the zcr_color_space_v1 object.
	 *
	 * Destroying the zcr_color_space_v1 which is active on a surface
	 * or an output does not change the color space of those objects.
	 */
	void (*destroy)(struct wl_client *client,
			struct wl_resource *resource);
};

